------------ define ------------
local TEXT_STATUE = {
    NORMAL = 1, -- 普通
    SELECT = 2, -- 选中
    SPECIAL = 3, -- 特殊
}
------------ define ------------


---@class BeginnerFortnightCellNode
---@field TextDayTitle                  	Game.Native.Common.UISwitchTextMeshPro
---@field ImgSelectGroup                	UnityEngine.RectTransform
---@field StateAvailable                	UnityEngine.RectTransform
---@field ImgReceivedMark               	UnityEngine.RectTransform
---@field ImgBgTomorrow                 	UnityEngine.RectTransform
---@field StateNotAvailable             	UnityEngine.RectTransform
---@field GoodNode                      	UnityEngine.RectTransform
---@field TextDay                       	TMPro.TextMeshProUGUI
---@field ImgBg                         	UnityEngine.RectTransform
