local BeginnerFortnightCellNode = Class("BeginnerFortnightCellNode")
function BeginnerFortnightCellNode:__init()
    self.btnAction = nil

end

function BeginnerFortnightCellNode:__delete()
    self.btnAction = nil

    self.controller = nil
end

---SetCallBack
---设置单击回调函数
function BeginnerFortnightCellNode:SetBtnCallBack(cb)
    self.btnAction = cb
end

function BeginnerFortnightCellNode:GetCellDt()
    return checkTable(self.cellDt)
end

function BeginnerFortnightCellNode:GetDay()
    return checkInt(self:GetCellDt().day)
end

function BeginnerFortnightCellNode:Awake()
    SetButtonAction(self.BtnCardSigninNode, function ()
        if type(self.btnAction) == 'function' then
            self.btnAction()
        end
    end)
end

function BeginnerFortnightCellNode:FreshBaseUI(data)
    self.cellDt = checkTable(data)
    if self.Rare then
        KTool.SetActive(self.Rare, data.ssrTag == 1)
    end
    local isSpecial = self.cellDt.tag == 1
    if self.ImgBg then
        self.ImgBg.transform.gameObject:EnsureComponent(typeof(CS.UnityEngine.UI.Extensions.Gradient2)).enabled = isSpecial
    end

    self.TextDay.text = self:GetDay()
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self:GetCellDt().rewardId)
    local goEnv = CfUtils.GetLuaScr(self.GoodNode, "Game.Behaviours.GoodNodeMB")
    self.normal = isSpecial and TEXT_STATUE.SPECIAL or TEXT_STATUE.NORMAL
    goEnv:SetClickButtonAction(function()
        if isTable(vo) then
            GameUtils.ShowCommonTipsBoard(self.GoodNode, vo.name, vo.desc, vo.quality, vo.id)
        end
    end)
    goEnv:Reload(
            {
                goodsId = vo.id,
                isShowNo = true, text = 'x' .. tostring(self:GetCellDt().rewardNum)
            }
    )
end

---是否显示当前天数的选中外框
function BeginnerFortnightCellNode:SetSelectedGroupShow(isShow)
    KTool.SetActive(self.ImgSelectGroup, isShow)
    CfUtils.SetScale(self.controller.gameObject, isShow and Vector3(1.1, 1.1, 0) or Vector3.one)
    --if isShow  then
    --    self:PlayOpenAnim()
    --end
end

function BeginnerFortnightCellNode:RefreshStatue(isCan, time, day)
    local isCanDraw       = checkBool(isCan)
    local checkTime       = checkInt(time)
    local today           = day and checkInt(day) or self:GetDay()
    local isAvailable     = isCanDraw and today == checkTime + 1
    local isTomorrow      = today == checkTime + 1
    local isReceived      = today <= checkTime

    if isCanDraw then
        isTomorrow = today == checkTime + 2
    end

    KTool.SetActive(self.StateAvailable, isAvailable)
    KTool.SetActive(self.ImgBgTomorrow, isTomorrow)
    KTool.SetActive(self.ImgReceivedMark, isReceived)
    self:SetSelectedGroupShow(isAvailable)

    --local normal = self.cellDt.tag == 1 and TEXT_STATUE.SPECIAL or TEXT_STATUE.NORMAL
    CfUtils.SetUISwitchText(self.TextDayTitle, isAvailable and TEXT_STATUE.SELECT or self.normal)
    CfUtils.SetUISwitchText(self.TextDay, isAvailable and TEXT_STATUE.SELECT or self.normal)
end

function BeginnerFortnightCellNode:PlayOpenAnim()
    CfUtils.PlayAnimator(self.ImgSelectGroup, "Go")
end

function BeginnerFortnightCellNode:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return BeginnerFortnightCellNode